48	
49	type Props = Record<string, unknown>;
50	
51	const getNodeBadgeText = (node: DiscourseNode): string => {
52	  return formatBadgeText(node.tag?.trim() || node.text);
53	};
54	
55	const getTagStyle = (node: DiscourseNode | undefined): React.CSSProperties => {
56	  const color = node?.canvasSettings?.color;
57	  if (!color) return { flexShrink: 0 };
58	  return { ...getNodeTagStyles(color), flexShrink: 0 };
59	};
60	
61	const renderHighlightedText = (
62	  text: string,
63	  keywords: string[],
64	): React.ReactNode =>
65	  splitWithHighlights(text, keywords).map((segment, index) =>
66	    segment.isMatch ? (
67	      <mark key={`${segment.text}-${index}`}>{segment.text}</mark>
68	    ) : (
69	      <React.Fragment key={`${segment.text}-${index}`}>
70	        {segment.text}
71	      </React.Fragment>
72	    ),
73	  );
74	
75	const ResultRow = ({
76	  active,
77	  keywords,
78	  nodeConfig,
79	  onClick,
80	  onMouseEnter,
81	  result,
82	}: {
83	  active: boolean;
84	  keywords: string[];
85	  nodeConfig: DiscourseNode | undefined;
86	  onClick: () => void;
87	  onMouseEnter: () => void;
88	  result: SearchResult;
89	}) => (
90	  <Button
91	    alignText="left"
92	    aria-selected={active}
93	    className="flex-none !items-start gap-2 !px-3 !py-2"
94	    fill
95	    minimal
96	    onClick={onClick}
97	    onMouseEnter={onMouseEnter}
98	    role="option"
99	    style={{
100	      background: active ? "rgba(167, 182, 194, 0.3)" : undefined,
101	      boxShadow: active ? "inset 3px 0 0 rgba(167, 182, 194, 0.3)" : undefined,
102	    }}
103	  >
104	    <Tag minimal style={getTagStyle(nodeConfig)}>
105	      {nodeConfig
106	        ? getNodeBadgeText(nodeConfig)
107	        : formatBadgeText(result.nodeTypeLabel)}
108	    </Tag>
109	    <span className="min-w-0 break-words text-sm leading-snug text-gray-900">
110	      {renderHighlightedText(stripTypePrefix(result.title), keywords)}
111	    </span>
