128	
129	  return (
130	    <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
131	      <div className="flex-none flex-row gap-2 border-b border-gray-200 px-5 py-3 text-xs text-gray-500">
132	        Created: {formatMetadataDate(result.createdAt)} · Last modified:{" "}
133	        {formatMetadataDate(result.lastModified)} · Author:{" "}
134	        {result.authorName || "Unknown"}
135	      </div>
136	      <div
137	        className="min-h-0 flex-1 overflow-y-auto border-t border-gray-200 px-5 py-3"
138	        onMouseDown={(event) => event.preventDefault()}
139	      >
140	        <div className="pointer-events-none">
141	          {isPage ? (
142	            <RenderRoamPage hideMentions key={result.uid} uid={result.uid} />
143	          ) : (
144	            <RenderRoamBlock key={result.uid} uid={result.uid} zoomPath />
145	          )}
146	        </div>
147	      </div>
148	    </div>
149	  );
150	};
151	
152	const AdvancedNodeSearchDialog = ({
153	  isOpen,
154	  onClose,
155	}: RoamOverlayProps<Props>) => {
156	  const [searchTerm, setSearchTerm] = useState("");
157	  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
158	  const [isIndexLoading, setIsIndexLoading] = useState(false);
159	  const [indexError, setIndexError] = useState(false);
160	  const [activeIndex, setActiveIndex] = useState(0);
161	  const [searchIndex, setSearchIndex] = useState<SearchIndex | null>(null);
162	  const [sort, setSort] = useState<SortConfig>(DEFAULT_SORT_CONFIG);
163	  const [discourseNodes, setDiscourseNodes] = useState<DiscourseNode[]>([]);
164	  const [selectedNodeTypeIds, setSelectedNodeTypeIds] = useState<string[]>([]);
165	  const [isTypeFilterPopoverOpen, setIsTypeFilterPopoverOpen] = useState(false);
166	  const resultsPanelRef = useRef<HTMLDivElement | null>(null);
167	  const inputRef = useRef<HTMLInputElement | null>(null);
168	  const [insertTarget, setInsertTarget] = useState<InsertTarget | null>(null);
169	
170	  const nodeConfigByType = Object.fromEntries(
171	    discourseNodes.map((node) => [node.type, node]),
172	  );
173	
174	  const { results, isSearching } = useAdvancedNodeSearchResults({
175	    debouncedSearchTerm,
176	    selectedNodeTypeIds,
177	    sort,
178	    isIndexLoading,
179	    indexError,
180	    searchIndex,
181	  });
182	
183	  const activeResult = results[activeIndex] ?? null;
184	  const keywords = getSearchKeywords(debouncedSearchTerm);
185	
186	  useEffect(() => {
187	    if (!isOpen) return;
188	
189	    setInsertTarget(snapshotInsertTarget());
190	
191	    const focusInput = () => inputRef.current?.focus();
192	
193	    focusInput();
194	    const rafId = requestAnimationFrame(focusInput);
195	    const timeoutId = window.setTimeout(focusInput, 0);
196	
197	    return () => {
198	      cancelAnimationFrame(rafId);
199	      window.clearTimeout(timeoutId);
200	    };
201	  }, [isOpen]);
202	
203	  useEffect(() => {
204	    if (!isOpen) {
205	      setSearchTerm("");
206	      setDebouncedSearchTerm("");
207	      setActiveIndex(0);
208	      setSort(DEFAULT_SORT_CONFIG);
209	      setSelectedNodeTypeIds([]);
210	      setSearchIndex(null);
211	      setIndexError(false);
212	    }
213	  }, [isOpen]);
214	
215	  useEffect(() => {
216	    let cancelled = false;
217	    setIsIndexLoading(true);
218	    setIndexError(false);
219	    setSearchIndex(null);
220	
221	    const discourseNodes = getDiscourseNodes().filter(
222	      (node) => node.backedBy === "user",
223	    );
224	    setDiscourseNodes(discourseNodes);
225	
226	    void buildSearchIndex(discourseNodes)
227	      .then(({ miniSearch, results: indexedResults }) => {
228	        if (cancelled) return;
229	        setSearchIndex({ miniSearch, allResults: indexedResults });
230	      })
231	      .catch((error) => {
232	        console.error("Error building advanced node search index:", error);
233	        if (cancelled) return;
234	        setIndexError(true);
235	        renderToast({
236	          id: "advanced-node-search-index-error",
237	          content: "Failed to load discourse nodes for search.",
238	          intent: "danger",
239	        });
240	      })
241	      .finally(() => {
242	        if (!cancelled) setIsIndexLoading(false);
243	      });
244	
245	    return () => {
246	      cancelled = true;
247	    };
248	  }, [isOpen]);
249	
250	  useEffect(() => {
251	    const timeout = setTimeout(
252	      () => setDebouncedSearchTerm(searchTerm.trim()),
253	      DEBOUNCE_MS,
254	    );
255	    return () => clearTimeout(timeout);
256	  }, [searchTerm]);
257	
258	  useEffect(() => {
259	    setActiveIndex(0);
260	  }, [debouncedSearchTerm, selectedNodeTypeIds, sort]);
261	
262	  useEffect(() => {
263	    const panel = resultsPanelRef.current;
264	    if (!panel) return;
265	
266	    const activeRow = panel.querySelector('[aria-selected="true"]');
267	    activeRow?.scrollIntoView({ block: "nearest" });
268	  }, [activeIndex, activeResult?.uid, debouncedSearchTerm]);
269	
270	  const onInsert = useCallback(async () => {
271	    if (!activeResult || !insertTarget) return;
272	
273	    const pageTitle =
274	      getPageTitleByPageUid(activeResult.uid) ??
275	      stripTypePrefix(activeResult.title);
276	
277	    await insertPageRefAtRange({
278	      blockUid: insertTarget.blockUid,
279	      pageTitle,
280	      selectionEnd: insertTarget.selectionEnd,
281	      selectionStart: insertTarget.selectionStart,
282	      windowId: insertTarget.windowId,
283	    });
284	
285	    posthog.capture("Advanced Node Search: Insert", {
286	      uid: activeResult.uid,
287	      pageTitle,
288	    });
289	    onClose();
290	  }, [activeResult, insertTarget, onClose]);
291	
292	  const contentState = indexError
293	    ? "error"
294	    : isIndexLoading || isSearching
295	      ? "indexing"
296	      : !debouncedSearchTerm && selectedNodeTypeIds.length === 0
297	        ? "initial"
298	        : !results.length
299	          ? "empty"
300	          : "results";
301	
302	  const onOpenSearchSidebar = useCallback(async () => {
303	    if (contentState !== "results" || !results.length) return;
304	
305	    try {
306	      await mountAdvancedSearchInSidebar({
307	        query: debouncedSearchTerm,
308	        results,
309	        selectedNodeTypeIds,
310	        sort,
311	      });
312	
313	      posthog.capture("Advanced Node Search: Dock search sidebar", {
314	        resultCount: results.length,
315	        searchTerm: debouncedSearchTerm,
316	        selectedNodeTypeCount: selectedNodeTypeIds.length,
317	        sortDirection: sort.direction,
318	        sortField: sort.field,
319	      });
320	      onClose();
321	    } catch (error) {
322	      console.error("Failed to dock search results in the sidebar:", error);
323	      renderToast({
324	        id: "advanced-node-search-sidebar-open-error",
325	        content: "Could not dock search results in the right sidebar.",
326	        intent: "danger",
327	      });
328	    }
329	  }, [
330	    contentState,
331	    debouncedSearchTerm,
332	    onClose,
333	    results,
334	    selectedNodeTypeIds,
335	    sort,
336	  ]);
337	  const handleSortChange = useCallback((nextSort: SortConfig): void => {
338	    setSort(nextSort);
339	  }, []);
340	
341	  const onOpen = useCallback(async () => {
342	    if (!activeResult || contentState !== "results") return;
343	
344	    const uid = activeResult.uid;
345	    if (getPageTitleByPageUid(uid)) {
346	      await window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } });
347	    } else {
348	      await window.roamAlphaAPI.ui.mainWindow.openBlock({ block: { uid } });
349	    }
350	    onClose();
351	  }, [activeResult, contentState, onClose]);
352	
353	  const onOpenInSidebar = useCallback(async () => {
354	    if (!activeResult || contentState !== "results") return;
355	
356	    await window.roamAlphaAPI.ui.rightSidebar.addWindow({
357	      window: {
358	        type: "outline",
359	        // @ts-expect-error - block-uid is valid for outline sidebar windows
360	        // eslint-disable-next-line @typescript-eslint/naming-convention
361	        "block-uid": activeResult.uid,
362	      },
363	    });
364	    onClose();
365	  }, [activeResult, contentState, onClose]);
366	
367	  const handleSearchKeyDown = useCallback(
368	    (event: React.KeyboardEvent): void => {
369	      if (event.key === "ArrowDown" && results.length) {
370	        event.preventDefault();
371	        setActiveIndex((index) =>
372	          Math.min(Math.max(index, 0) + 1, results.length - 1),
373	        );
374	        return;
375	      }
376	      if (event.key === "ArrowUp" && results.length) {
377	        event.preventDefault();
378	        setActiveIndex((index) => Math.max(index - 1, 0));
379	        return;
380	      }
381	      if (
382	        event.key === "Enter" &&
383	        event.altKey &&
384	        contentState === "results" &&
385	        results.length
386	      ) {
387	        event.preventDefault();
388	        void onOpenSearchSidebar();
389	      } else if (
390	        event.key === "Enter" &&
391	        !event.metaKey &&
392	        !event.ctrlKey &&
393	        contentState === "results" &&
394	        activeResult
395	      ) {
396	        event.preventDefault();
397	        if (event.shiftKey) void onOpenInSidebar();
398	        else void onOpen();
399	        return;
400	      }
401	      if (
402	        event.key === "Enter" &&
403	        (event.metaKey || event.ctrlKey) &&
404	        contentState === "results" &&
405	        activeResult &&
406	        insertTarget
407	      ) {
408	        event.preventDefault();
409	        void onInsert();
410	        return;
411	      }
412	      if (event.key === "Escape") {
413	        if (isTypeFilterPopoverOpen) return;
414	        event.preventDefault();
415	        onClose();
416	      }
417	    },
418	    [
419	      activeResult,
420	      contentState,
421	      isTypeFilterPopoverOpen,
422	      insertTarget,
423	      onClose,
424	      onOpenSearchSidebar,
425	      onInsert,
426	      onOpen,
427	      onOpenInSidebar,
428	      results.length,
429	    ],
430	  );
431	
432	  const onKeyDown = useCallback(
433	    (event: React.KeyboardEvent<HTMLDivElement>) => {
434	      if (event.defaultPrevented) return;
435	      handleSearchKeyDown(event);
436	    },
437	    [handleSearchKeyDown],
438	  );
439	
440	  const showSplitView = contentState === "results";
441	
442	  return (
443	    <Dialog
444	      autoFocus={false}
445	      canEscapeKeyClose
446	      canOutsideClickClose
447	      className="flex w-full max-w-4xl flex-col overflow-hidden bg-white p-0"
448	      enforceFocus={false}
449	      isOpen={isOpen}
450	      onClose={onClose}
451	      style={{
452	        height: "72vh",
453	        width: "min(56rem, calc(100vw - 64px))",
454	      }}
455	    >
456	      <div
457	        onClick={(event) => event.stopPropagation()}
458	        onKeyDown={onKeyDown}
459	        onMouseDown={(event) => event.stopPropagation()}
460	        onMouseUp={(event) => event.stopPropagation()}
461	        className="flex min-h-0 flex-1 flex-col overflow-hidden"
462	      >
463	        <div className="flex w-full flex-none items-start gap-2 border-b border-gray-200 px-3 py-2">
464	          <div className="flex min-h-9 min-w-0 flex-1 items-center rounded border border-gray-300 bg-white px-2 py-1">
465	            <Icon
466	              className="mr-2 shrink-0 self-center text-gray-500"
467	              icon="search"
468	              size={16}
469	            />
470	            <NodeTypeChipsSearchInput
471	              inputRef={inputRef}
472	              nodeTypes={discourseNodes}
473	              onSearchKeyDown={handleSearchKeyDown}
474	              onSearchTermChange={setSearchTerm}
475	              onSelectedTypeIdsChange={setSelectedNodeTypeIds}
476	              searchTerm={searchTerm}
477	              selectedTypeIds={selectedNodeTypeIds}
478	            />
479	          </div>
480	          <DiscourseNodeTypeFilter
481	            layoutAnchorKey={selectedNodeTypeIds.length}
482	            nodeTypes={discourseNodes}
483	            onPopoverOpenChange={setIsTypeFilterPopoverOpen}
484	            onSelectedTypeIdsChange={setSelectedNodeTypeIds}
485	            selectedTypeIds={selectedNodeTypeIds}
486	          />
487	          <DiscourseNodeSortControl
488	            disabled={isIndexLoading || indexError}
489	            onSortChange={handleSortChange}
490	            sort={sort}
491	          />
492	          <Button
493	            className="shrink-0"
494	            icon="cross"
495	            minimal
496	            onClick={onClose}
497	            title="Close search"
498	          />
499	        </div>
500	        <div className="flex min-h-0 w-full flex-1 overflow-hidden">
501	          {showSplitView ? (
502	            <>
503	              <div
504	                aria-label="Search results"
505	                className="w-1/3 shrink-0 overflow-y-auto border-r border-gray-200 py-1"
506	                ref={resultsPanelRef}
507	                role="listbox"
508	              >
509	                {results.map((result, index) => (
510	                  <ResultRow
511	                    active={index === activeIndex}
512	                    key={result.uid}
513	                    keywords={keywords}
514	                    nodeConfig={nodeConfigByType[result.type]}
515	                    onClick={() => setActiveIndex(index)}
516	                    onMouseEnter={() => setActiveIndex(index)}
517	                    result={result}
518	                  />
519	                ))}
520	              </div>
521	              <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
522	                <PreviewPane result={activeResult} />
523	              </div>
524	            </>
525	          ) : (
526	            <div className="flex min-h-0 w-full flex-1 items-center justify-center px-4 py-8 text-center text-sm text-gray-500">
527	              {contentState === "indexing" && (
528	                <Spinner size={SpinnerSize.SMALL} />
529	              )}
530	              {contentState === "empty" && (
531	                <span>No matches. Try another keyword or filter.</span>
532	              )}
533	              {contentState === "error" && (
534	                <span>
535	                  Search unavailable. Reload the extension and try again.
536	                </span>
537	              )}
538	            </div>
539	          )}
540	        </div>
541	        <AdvancedSearchFooter
542	          contentState={contentState}
543	          hasActiveResult={!!activeResult}
544	          insertTarget={insertTarget}
545	          onInsert={() => void onInsert()}
546	          onOpen={() => void onOpen()}
547	          onOpenInSidebar={() => void onOpenInSidebar()}
548	          onOpenSearchSidebar={() => void onOpenSearchSidebar()}
549	        />
550	      </div>
551	    </Dialog>
552	  );
553	};
