1	import { useEffect, useMemo, useState } from "react";
2	import MiniSearch from "minisearch";
3	import getDiscourseNodes from "~/utils/getDiscourseNodes";
4	import { searchDiscourseNodes } from "~/utils/searchDiscourseNodes";
5	import {
6	  searchDiscourseNodesWithMiniSearch,
7	  sortSearchResults,
8	  type ScoredSearchResult,
9	  type SearchResult,
10	  type SortConfig,
11	} from "./utils";
12	
13	export type SearchIndex = {
14	  miniSearch: MiniSearch<SearchResult & { id: string }>;
15	  allResults: SearchResult[];
16	};
17	
18	type UseAdvancedNodeSearchResultsArgs = {
19	  debouncedSearchTerm: string;
20	  selectedNodeTypeIds: string[];
21	  sort: SortConfig;
22	  isIndexLoading: boolean;
23	  indexError: boolean;
24	  searchIndex: SearchIndex | null;
25	  dockedQuery?: string;
26	  dockedResults?: SearchResult[];
27	};
28	
29	export const useAdvancedNodeSearchResults = ({
30	  debouncedSearchTerm,
31	  selectedNodeTypeIds,
32	  sort,
33	  isIndexLoading,
34	  indexError,
35	  searchIndex,
36	  dockedQuery,
37	  dockedResults,
38	}: UseAdvancedNodeSearchResultsArgs): {
39	  results: SearchResult[];
40	  isSearching: boolean;
41	} => {
42	  // An empty persisted result set is not a usable cache: the docked panel also
43	  // persists the transient [] published while an async search is in flight.
44	  const hasUsableDockedResults = useMemo(
45	    () =>
46	      dockedQuery !== undefined &&
47	      debouncedSearchTerm.trim() === dockedQuery.trim() &&
48	      !!dockedResults &&
49	      dockedResults.length > 0,
50	    [debouncedSearchTerm, dockedQuery, dockedResults],
51	  );
52	
53	  const [unsortedScoredResults, setUnsortedScoredResults] = useState<
54	    ScoredSearchResult[]
55	  >([]);
